import time
from random import randint, sample

def get_random_num(min, max):
    return randint(min, max)

def get_max_conscepcion():
    return int(input("Enter maximum number of consecutive failures before considering a retrysuccessful: "))

def main():
    # Initialize variables
    max_conscepcion = get_max_conscepcion()

    # Generate random solutions with specified number of failures
    num_failures = sample(range(1, max_conscepcion+1), 5)
    solutions = []
    for _ in range(num_failures):
        solutions.append([])

    # Loop through solutions and check if any solution is successful
    for i in range(len(solutions)):
        for j in range(i+1, len(solutions)):
            if solutions[j][0] == solutions[i][0]:
                solutions[i].append([])

    # Calculate average number of consecutive failures
    avg_conscepcion = sum(map(lambda x: sum(x), solutions)) / len(solutions)

    # Print results
    print("Average number of consecutive failures:", avg_conscepcion)

    # Run program
    time.sleep(10)
    main()

if __name__ == "__main__":
    main()
